head=r'''// Football scoreboard - SPX calls update(), play(), stop(), next().
// The goal flag and the full-time look are machine states (operator buttons); paintBoard()
// makes the board's classes and words agree with the machine and the data.

var onAir = false;               // true between play() and stop() - score pops only on air
var scoreIds = ['f1', 'f3'];

function motionSpeed() {
  if (typeof NOACG_ANIM !== 'undefined' && NOACG_ANIM.speed) return NOACG_ANIM.speed;
  return 1;
}

// Operator text is written as plain text, never HTML.
function setFieldValue(el, value) {
  if (el.tagName === 'IMG') {
    if (value) { el.src = value; el.style.display = ''; }
    else { el.removeAttribute('src'); el.style.display = 'none'; }
  } else {
    el.textContent = value == null ? '' : String(value);
  }
}

function textOf(id) {
  var el = document.getElementById(id);
  return el ? (el.textContent || '') : '';
}

// paintBoard(): classes on the root from the machine (goal side, final), and the words the
// flag and the final tab show, from the hidden word sources and the team names.
function paintBoard() {
  var root = document.querySelector('.scoreboard');
  if (!root) return;
  var groups = {};
  if (typeof noacgMachineState === 'function') groups = (noacgMachineState() || {}).groups || {};
  var flag = groups.flag;
  var isFinal = groups.result === 'final';
  root.classList.toggle('scoreboard-goal-a', flag === 'flagA');
  root.classList.toggle('scoreboard-goal-b', flag === 'flagB');
  root.classList.toggle('scoreboard-flagged', flag === 'flagA' || flag === 'flagB');
  root.classList.toggle('scoreboard-final', isFinal);
  var word = root.querySelector('.scoreboard-flag-word');
  if (word) word.textContent = textOf('f4');
  // The flag keeps the last scorer's name while it animates away, so it is only rewritten
  // while a side is flagged.
  var team = root.querySelector('.scoreboard-flag-team');
  if (team && flag === 'flagA') team.textContent = textOf('f0');
  if (team && flag === 'flagB') team.textContent = textOf('f2');
  var fin = root.querySelector('.scoreboard-final-word');
  if (fin) fin.textContent = textOf('f5');
}

// The state calls (each safe to run twice: a recovery snap fires them again).
function markGoal() { paintBoard(); }
function clearGoal() { paintBoard(); }
function markFinal() { paintBoard(); }
function markLive() { paintBoard(); }
// Take puts every group back to its initial state without playing those timelines: the
// entrance step's keyframes hide the flag and the tab, and this repaints the classes.
function resetOnTake() { paintBoard(); }

function update(data) {
  var fields = (typeof data === 'string') ? JSON.parse(data) : data;
  for (var key in fields) {
    var el = document.getElementById(key);
    if (!el) continue;
    var changed = el.textContent !== String(fields[key]);
    setFieldValue(el, fields[key]);
    if (changed && onAir && scoreIds.indexOf(key) !== -1 && el.parentNode) {
      // pop the mask (not the span) so two-digit scores are never clipped
      gsap.fromTo(el.parentNode, { scale: 1.4 }, { scale: 1, duration: 0.45 / motionSpeed(), ease: 'back.out(1.7)' });
    }
  }
  paintBoard();
}

function resetScorePop() {
  for (var i = 0; i < scoreIds.length; i++) {
    var el = document.getElementById(scoreIds[i]);
    if (el && el.parentNode) gsap.set(el.parentNode, { scale: 1 });
  }
}

function play() {
  gsap.killTweensOf('*');
  resetScorePop();
  onAir = true;
  buildInTimeline();
}

function stop() {
  gsap.killTweensOf('*');
  resetScorePop();
  onAir = false;
  buildOutTimeline();
}

function next() {
  return (typeof revealNextStep === 'function') ? revealNextStep() : null;
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', paintBoard);
} else {
  paintBoard();
}

'''
